(()=>{
const $=id=>document.getElementById(id);let result;
const sources=[
 ['Orch OR','Hypothesis','Microtubule quantum processes and proposed objective reduction are linked to conscious moments. This simulation does not implement that proposal.','https://pubmed.ncbi.nlm.nih.gov/24070914/'],
 ['Nuclear-spin proposal','Hypothesis','Fisher proposes a route from protected nuclear spins to neural processing. Biological realization and relevance to experience require evidence.','https://doi.org/10.1016/j.aop.2015.08.020'],
 ['Protein optical effects','Experiment','Collective optical effects in protein structures motivate biophysical research. They do not establish conscious quantum computation in a brain.','https://arxiv.org/abs/2302.01469'],
 ['Microtubules & anesthesia','Experiment','A rat study found delayed loss of righting reflex after a microtubule-stabilizing drug. It did not isolate a quantum mechanism; the reflex is a proxy.','https://www.eneuro.org/content/11/8/ENEURO.0291-24.2024'],
 ['Quantum cognition','Mathematical model','Quantum probability can model judgment order effects without assuming physical quantum computation in the brain.','https://pmc.ncbi.nlm.nih.gov/articles/PMC4084470/'],
 ['Decoherence debate','Constraint','Estimated coherence lifetimes depend on the chosen states and environment. A generic warm-brain argument does not settle every proposal.','https://doi.org/10.1103/PhysRevE.65.061901']
];
$('theorySources').innerHTML=sources.map(([name,type,body,url])=>`<article><span class="tag">${type}</span><h3>${name}</h3><p>${body}</p><a href="${url}" target="_blank" rel="noopener noreferrer">Read original source ↗</a></article>`).join('');
function draw(){
 const row=result.rows[+$('theoryReplay').value];$('theoryStep').textContent=`Delay ${row.step} / ${result.protocol.steps}`;
 $('theoryProbability').textContent=(100*row.quantum).toFixed(1)+'%';$('theoryCoherence').textContent=row.coherence.toFixed(3);$('theoryPurity').textContent=row.purity.toFixed(3);
 const X=r=>48+r.step/result.protocol.steps*640,Y=v=>220-v*190;
 const path=key=>result.rows.map((r,i)=>(i?'L':'M')+X(r).toFixed(2)+','+Y(r[key]).toFixed(2)).join(' ');
 $('theoryChart').innerHTML=`<svg viewBox="0 0 740 280" role="img" aria-label="Probability of outcome zero by abstract delay step, quantum and classical curves overlap; sampled estimates have 95 percent pointwise Wilson intervals"><text x="48" y="15" fill="currentColor" font-size="12">Probability of outcome 0</text>${[0,.5,1].map(v=>`<line x1="48" x2="688" y1="${Y(v)}" y2="${Y(v)}" stroke="#334155"/><text x="8" y="${Y(v)+4}" fill="currentColor" font-size="12">${v}</text>`).join('')}<path d="${path('noMemory')}" fill="none" stroke="#8190a0" stroke-dasharray="3 6"/><path d="${path('quantum')}" fill="none" stroke="#64d1e6" stroke-width="4"/><path d="${path('classical')}" fill="none" stroke="#ff866f" stroke-width="2" stroke-dasharray="7 5"/>${result.rows.map(r=>`<line x1="${X(r)}" x2="${X(r)}" y1="${Y(r.interval95[0])}" y2="${Y(r.interval95[1])}" stroke="#b8a0e8" opacity=".6"/><circle cx="${X(r)}" cy="${Y(r.stochastic)}" r="2.5" fill="#b8a0e8"/>`).join('')}<line x1="${X(row)}" x2="${X(row)}" y1="25" y2="225" stroke="#fff" opacity=".5"/><text x="48" y="245" fill="currentColor" font-size="12">0</text><text x="675" y="245" fill="currentColor" font-size="12">${result.protocol.steps}</text><text x="240" y="270" fill="currentColor" font-size="12">Delay (abstract steps, not seconds)</text></svg>`;
 $('theoryState').textContent=`Bloch vector (${row.bloch.x.toFixed(3)}, ${row.bloch.y.toFixed(3)}, 0). Density-matrix populations remain ½, ½ before readout. Off-diagonal entry: (${(row.bloch.x/2).toFixed(3)}) − i(${(row.bloch.y/2).toFixed(3)}).`;
}
function run(){try{result=TheoryLab.run({steps:+$('tSteps').value,phase:+$('tPhase').value,dephasing:+$('tNoise').value,shots:+$('tShots').value,seed:+$('tSeed').value,intervention:$('tIntervention').value,at:+$('tAt').value});$('theoryReplay').max=result.protocol.steps;$('theoryReplay').value=result.protocol.steps;$('theorySummary').textContent=`Quantum–oscillator maximum gap: ${result.maxDifference.toExponential(2)}. Sampling RMSE: ${result.samplingRMSE.toFixed(4)}. The two exact models agree within floating-point precision. This experiment cannot identify a physical substrate.`;$('theoryProtocol').textContent=`Executed: ${result.protocol.steps} steps · ${result.protocol.phase}°/step · dephasing ${result.protocol.dephasing} · ${result.protocol.shots} preparations per delay · seed ${result.protocol.seed} · ${result.protocol.intervention} at step ${result.protocol.at}`;$('theoryStatus').textContent='Experiment complete. Edit controls and run again to update results.';draw();}catch(e){$('theoryStatus').textContent=e.message;}}
$('theoryRun').onclick=run;$('theoryReplay').oninput=draw;$('theoryExport').onclick=()=>download('qualia-theory-experiment.json',JSON.stringify(result,null,2));
$('theoryPreset').onchange=()=>{const v=$('theoryPreset').value;$('tNoise').value=v==='dephase'?.15:v==='custom'?.04:0;$('tIntervention').value=v==='erase'?'erase':v==='flip'?'flip':'none';$('tPhase').value=45;$('tAt').value=v==='custom'?12:16;$('tSteps').value=32;run();};
run();
})();
